fun findFirstRepeatingCharacter(input: String): Char {
    val seen = mutableSetOf<Char>()
    for (char in input) if (!seen.add(char)) return char
    return '\u0000'
}

fun findFirstRepeatingCharacter(input: String): Char {
    val seen = mutableSetOf<Char>()
    for (char in input) {
        if (char in seen) return char
        seen.add(char)
    }
    return '\u0000'

}

fun findFirstRepeatingCharacter(input: String): Char {
    return input.asSequence().groupingBy { it }.eachCount().let { counts -> input.first { counts[it]!! > 1 } }
}
